static const char scan_comp[] =
    "#version 310 es\n"
    "// The neighbour grid, 1 of 2: the cells' first places (an exclusive prefix\n"
    "// sum of the 4096 counts, one work group, in shared memory); the counts\n"
    "// zeroed for the next count. starts has one entry more than cells: the\n"
    "// total.\n"
    "layout(local_size_x = 128) in;\n"
    "layout(std430, binding = 2) buffer Counts { uint c[]; } counts;\n"
    "layout(std430, binding = 3) writeonly buffer Starts { uint s[]; } starts;\n"
    "shared uint part[128];\n"
    "\n"
    "void main()\n"
    "{\n"
    "    uint t = gl_LocalInvocationID.x, base = t * 32u, sum = 0u, k, d;\n"
    "    for (k = 0u; k < 32u; k++)\n"
    "        sum += counts.c[base + k];\n"
    "    part[t] = sum;\n"
    "    barrier();\n"
    "    for (d = 1u; d < 128u; d <<= 1) { // inclusive scan of the 128 sums\n"
    "        uint v = t >= d ? part[t - d] : 0u;\n"
    "        barrier();\n"
    "        part[t] += v;\n"
    "        barrier();\n"
    "    }\n"
    "    sum = part[t] - sum; // exclusive: this run's start\n"
    "    for (k = 0u; k < 32u; k++) {\n"
    "        uint c = counts.c[base + k];\n"
    "        starts.s[base + k] = sum;\n"
    "        counts.c[base + k] = 0u;\n"
    "        sum += c;\n"
    "    }\n"
    "    if (t == 127u)\n"
    "        starts.s[4096] = sum;\n"
    "}\n"
    ;

