static const char wave_comp[] =
    "#version 310 es\n"
    "// The ball's skin as water: a height field over the ball's surface (128\n"
    "// cells round by 64 from the bottom pole to the top, turning with the ball,\n"
    "// so a ripple stays where its drop fell), one step of the wave equation a\n"
    "// dispatch.\n"
    "// Each cell keeps (height, the height a step before); a step reads `src`\n"
    "// and writes `dst` (the program swaps them, a step a frame). Drops fall\n"
    "// on it at random places (u_drop), each spreading as a ring; the mouse\n"
    "// (u_poke: its cell, and strength) dents the skin where it touches.\n"
    "// sim.comp shows each boid lifted by the height there.\n"
    "layout(local_size_x = 128) in;\n"
    "layout(std430, binding = 6) readonly buffer Src { vec2 c[]; } src;\n"
    "layout(std430, binding = 7) writeonly buffer Dst { vec2 c[]; } dst;\n"
    "uniform vec3 u_drop; // a drop: its lon and lat cell, strength (0: none)\n"
    "uniform vec3 u_poke; // lon and lat cell, strength (0: none)\n"
    "\n"
    "float h(int i, int j)\n"
    "{\n"
    "    // up and down past a pole: reflect (the pole rows are its neighbours)\n"
    "    j = clamp(j, 0, 63);\n"
    "    return src.c[j * 128 + (i & 127)].x;\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "    int i = int(gl_LocalInvocationID.x), j = int(gl_WorkGroupID.x);\n"
    "    vec2 c = src.c[j * 128 + i];\n"
    "    float lap = h(i + 1, j) + h(i - 1, j) + h(i, j + 1) + h(i, j - 1) - 4.0 * c.x;\n"
    "    // damped, more near the poles (the grid's rings shrink there: the\n"
    "    // waves would heap up into spikes)\n"
    "    float pole = min(float(j), float(63 - j));\n"
    "    float n = (2.0 * c.x - c.y + 0.08 * lap) * (pole < 4.0 ? 0.9 + 0.02 * pole : 0.997);\n"
    "    if (u_drop.z != 0.0) {\n"
    "        vec2 d = vec2(float(i) - u_drop.x, float(j) - u_drop.y);\n"
    "        d.x -= 128.0 * round(d.x / 128.0);\n"
    "        n += u_drop.z * exp(-dot(d, d) * 0.35);\n"
    "    }\n"
    "    if (u_poke.z != 0.0) {\n"
    "        vec2 d = vec2(float(i) - u_poke.x, float(j) - u_poke.y);\n"
    "        d.x -= 128.0 * round(d.x / 128.0); // round the ball\n"
    "        n -= u_poke.z * exp(-dot(d, d) * 0.25);\n"
    "    }\n"
    "    dst.c[j * 128 + i] = vec2(clamp(n, -4.0, 4.0), c.x);\n"
    "}\n"
    ;

