    "uniform float u_ring;  // 0: the text; 1: Saturn's rings (text_home)\n"
    "uniform float u_ringt; // the rings' time\n"
    "uniform float u_storm; // 0..1: the text boids let go into a storm round the ball\n"
    "uniform float u_tpull; // the text boids' pull (0..1: forming as the text scrolls in)\n"
    "uniform highp sampler2D u_text; // each text boid's place on the ring (angle, height, depth)\n"
    "uniform int u_max;\n"
    "uniform int u_every;\n"
    "uniform float u_dt;\n"
    "uniform float u_time;\n"
    "uniform float u_spin;\n"
    "uniform float u_pull;\n"
    "uniform float u_flow;\n"
    "uniform float u_burst;\n"
    "uniform float u_stripe;\n"
    "uniform vec4 u_hawk;\n"
    "uniform float u_skin; // how much the skin shows: 0..1, faded in once the ball has formed\n"
    "uniform vec3 u_centre;   // the ball's\n"
    "uniform vec3 u_wander;   // the murmuration's\n"
    "\n"
    "// The skin's height at the unit direction d from the ball's centre: its\n"
    "// four nearest cells mixed (128 round, 64 from the bottom pole up).\n"
    "float skin_at(vec3 d)\n"
    "{\n"
    "    float u = (atan(d.z, d.x) / 6.2831853 + 0.5) * 128.0 - 0.5;\n"
    "    float v = (asin(clamp(d.y, -1.0, 1.0)) / 3.1415927 + 0.5) * 64.0 - 0.5;\n"
    "    int i = int(floor(u)), j = int(floor(v));\n"
    "    float fu = u - float(i), fv = v - float(j);\n"
    "    int j0 = clamp(j, 0, 63), j1 = clamp(j + 1, 0, 63), i0 = i & 127, i1 = (i + 1) & 127;\n"
    "    return mix(mix(skin.c[j0 * 128 + i0].x, skin.c[j0 * 128 + i1].x, fu),\n"
    "               mix(skin.c[j1 * 128 + i0].x, skin.c[j1 * 128 + i1].x, fu), fv);\n"
    "}\n"
    "\n"
    "// Boid i's place on a ball of radius 3 (a Fibonacci sphere), spun about the\n"
    "// tilted axis; w: 1 for a red check (16 across, 8 down), 0 for a white one.\n"
    "vec4 home(int i)\n"
    "{\n"
    "    float y = 1.0 - 2.0 * (float(i) + 0.5) / float(u_ball);\n"
    "    float r = sqrt(max(1.0 - y * y, 0.0));\n"
    "    float phi = mod(float(i) * 2.3999632, 6.2831853);\n"
    "    float lon = mod(phi + u_spin, 6.2831853);\n"
    "    float check = mod(floor(phi * 2.5464791) + floor((y + 1.0) * 4.0), 2.0);\n"
    "    vec3 p = vec3(cos(lon) * r, y, sin(lon) * r) * 3.0;\n"
    "    float c = 0.9553365, s = 0.2955202; // the 1984 ball's tilt, 0.3 rad\n"
    "    vec3 w = vec3(c * p.x - s * p.y, s * p.x + c * p.y, p.z);\n"
    "    return vec4(u_centre + w, check);\n"
    "}\n"
    "\n"
    "// Text boid i's place: OGLES3 in lights on a ring of radius 5.4 round the\n"
    "// ball, turning (u_orbit); its angle, height and depth from u_text (made by\n"
    "// the 68k once from the stats' font). White.\n"
    "// Once the ball has been whole a while the text turns into Saturn's rings\n"
    "// (u_ring 0..1): in the ball's tilted equator, an inner band (3.7-4.85)\n"
    "// and an outer one (5.1-5.75) with a gap between, each boid orbiting as a\n"
    "// moon does (the inner faster; u_ringt the rings' time).\n"
    "vec4 text_home(int i)\n"
    "{\n"
    "    int k = i - u_ball;\n"
    "    vec4 t = texelFetch(u_text, ivec2(k & 127, k >> 7), 0);\n"
    "    float a = t.x + u_orbit, rr = 5.4 + t.z;\n"
    "    vec3 txt = vec3(cos(a) * rr, t.y, sin(a) * rr);\n"
    "    if (u_ring <= 0.0)\n"
    "        return vec4(u_centre + txt, 0.0);\n"
    "    float u = fract(float(k) * 0.7548777), v = fract(float(k) * 0.5698403), w = fract(float(k) * 0.6180340);\n"
    "    float r = u < 0.62 ? 3.7 + 1.15 * (u / 0.62) : 5.1 + 0.65 * ((u - 0.62) / 0.38);\n"
    "    float ra = v * 6.2831853 + u_ringt * pow(3.7 / r, 1.5);\n"
    "    vec3 q = vec3(cos(ra) * r, (w - 0.5) * 0.06, sin(ra) * r);\n"
    "    float c = 0.9553365, s = 0.2955202; // the ball's tilt\n"
    "    q = vec3(c * q.x - s * q.y, s * q.x + c * q.y, q.z);\n"
    "    return vec4(u_centre + mix(txt, q, u_ring), 0.0);\n"
    "}\n"
    "\n"
    "// The murmuration's flow: a swirl round the vertical axis through c\n"
    "// (u_wander; the ball's centre for the text's storm), folded by slow waves,\n"
    "// and drawn back towards it beyond a radius of 6.\n"
    "vec3 flow(vec3 p, vec3 c)\n"
    "{\n"
    "    vec3 d = p - c;\n"
    "    vec3 swirl = normalize(vec3(-d.z, 0.0, d.x) + vec3(0.0001));\n"
    "    vec3 wave = vec3(sin(p.y * 0.9 + u_time * 0.7), sin(p.z * 0.8 - u_time * 0.5) * 0.8,\n"
    "                     cos(p.x * 0.7 + u_time * 0.6));\n"
    "    float far = max(length(d) - 6.0, 0.0);\n"
    "    return (swirl * 2.0 + wave * 2.8) - d * far * 0.3;\n"
    "}\n"
    "\n"
    "uint cell_of(vec3 p)\n"
    "{\n"
    "    ivec3 g = ivec3(floor(p * 2.0)) & 15;\n"
    "    return uint(g.x + 16 * (g.y + 16 * g.z));\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "    int i = int(gl_GlobalInvocationID.x);\n"
    "    if (i >= u_n)\n"
    "        return;\n"
    "    vec3 p = src.b[i].pos.xyz, v = src.b[i].vel.xyz;\n"
    "    vec3 r = fract(vec3(float(i) * 0.6180340, float(i) * 0.7548777, float(i) * 0.5698403)) - 0.5;\n"
    "    bool text = i >= u_ball;\n"
    "    vec4 h = text ? text_home(i) : home(i);\n"
    "    float pull = u_pull, fl = u_flow;\n"
    "    if (u_stripe >= 0.0) { // the return: band by band, from the bottom (the text last)\n"
    "        float band = text ? 0.875 : floor((2.0 - 2.0 * (float(i) + 0.5) / float(u_ball)) * 4.0) / 8.0;\n"
    "        pull = smoothstep(band * 0.75, band * 0.75 + 0.25, u_stripe);\n"
    "        fl = 1.0 - pull;\n"
    "    }\n"
    "    // The text forms on its own clock, in 1.5 s, as it scrolls (u_tpull);\n"
    "    // in its storm (u_storm 0..1, after the rings) it is let go into the\n"
    "    // murmuration's flow round the ball, kept out of it.\n"
    "    vec3 fc = u_wander;\n"
    "    if (text)\n"
    "        pull = u_tpull, fl = 1.0 - pull;\n"
    "    bool storm = text && u_storm > 0.0;\n"
    "    if (storm) {\n"
    "        fl += pull * u_storm;\n"
    "        pull *= 1.0 - u_storm;\n"
    "        fc = u_centre;\n"
    "    }\n"
    "    vec3 a = (h.xyz - p) * (9.0 * pull) - v * (0.8 + 3.2 * pull);\n"
    "    if (fl > 0.0) // (the flow's sines skipped on the held ball)\n"
    "        a += (flow(p, fc) - v) * (1.2 * fl);\n"
    "    if (storm) {\n"
    "        vec3 d = p - u_centre;\n"
    "        float l = length(d) + 0.001;\n"
    "        if (l < 3.8)\n"
    "            a += d / l * ((3.8 - l) * 30.0 * u_storm);\n"
    "    }\n"
    "    if (u_hawk.w > 0.0) { // flee the mouse\n"
    "        vec3 d = p - u_hawk.xyz;\n"
    "        float l = length(d);\n"
    "        if (l < 2.2)\n"
    "            a += d / (l + 0.05) * (60.0 * (1.0 - l / 2.2) * u_hawk.w);\n"
    "    }\n"
    "    if (u_burst > 0.0) {\n"
    "        vec3 d = p - u_centre;\n"
    "        // outwards, each boid a little off its own way and speed: a storm,\n"
    "        // not a growing ball\n"
    "        v += normalize(normalize(d + vec3(0.0001)) + r * 1.4) * u_burst * (0.4 + 0.6 * fract(float(i) * 0.4142136));\n"
    "    }\n"
    "    // A u_every-th of the boids look round, by work group (the GPU runs 16\n"
    "    // boids side by side): the group's turn by a float product, not an\n"
    "    // integer modulo (the QPU has no division). The ball's boids and the\n"
    "    // text's flock apart. Held fast (pull 1: the formed ball, the text) the\n"
    "    // spring alone places a boid: no looking round then. A boid looks in the\n"
    "    // 8 cells on its side of its own (its octant's), not all 27: at most\n"
    "    // u_max are looked at anyway, and each cell costs two chained reads.\n"
    "    int grp = i >> 7;\n"
    "    if (pull < 0.999 && grp - int((float(grp) + 0.5) * u_einv) * u_every == u_look) {\n"
    "        vec3 sep = vec3(0.0), avel = vec3(0.0), apos = vec3(0.0);\n"
    "        float seen = 0.0;\n"
    "        int looked = 0;\n"
    "        ivec3 g = ivec3(floor(p * 2.0)), o = ivec3(step(0.5, fract(p * 2.0))) * 2 - 1;\n"
    "        for (int dz = 0; dz < 2 && looked < u_max; dz++)\n"
    "            for (int dy = 0; dy < 2 && looked < u_max; dy++)\n"
    "                for (int dx = 0; dx < 2 && looked < u_max; dx++) {\n"
    "                    ivec3 q = (g + ivec3(dx, dy, dz) * o) & 15;\n"
    "                    uint c = uint(q.x + 16 * (q.y + 16 * q.z));\n"
    "                    uint k = starts.s[c], e = starts.s[c + 1u];\n"
    "                    for (; k < e && looked < u_max; k++, looked++) {\n"
    "                        uint j = sorted.i[k];\n"
    "                        vec3 d = src.b[j].pos.xyz - p;\n"
    "                        float d2 = dot(d, d);\n"
    "                        if (j == uint(i) || d2 > 0.25 || (int(j) >= u_ball) != text)\n"
    "                            continue;\n"
    "                        sep -= d / (d2 + 0.01);\n"
    "                        avel += src.b[j].vel.xyz;\n"
    "                        apos += d;\n"
    "                        seen += 1.0;\n"
    "                    }\n"
    "                }\n"
    "        if (seen > 0.0)\n"
    "            a += (sep * 0.02 + (avel / seen - v) * 0.5 + apos / seen * 0.5) * float(u_every);\n"
    "    }\n"
    "    v += a * u_dt;\n"
    "    float s = length(v); // free boids fly at most 9 units a second\n"
    "    if (s > 9.0)\n"
    "        v *= 9.0 / s;\n"
    "    p += v * u_dt;\n"
    "    if (p.y < 0.05) { // the floor: slide along it\n"
    "        p.y = 0.05;\n"
    "        v.y = abs(v.y) * 0.3;\n"
    "        v.xz *= 1.0 - 1.5 * u_dt;\n"
    "    }\n"
    "    dst.b[i].pos = vec4(p, h.w);\n"
    "    dst.b[i].vel = vec4(v, 0.0);\n"
    "    // w for the draw: the check (1 red) plus the speed's share of 12 units a\n"
    "    // second (fast boids glow brighter and whiter)\n"
    "    // Shown lifted by the skin (held boids: by the pull), at once: the pull\n"
    "    // alone would smooth a quick ripple away. The skin turns with the ball\n"
    "    // (read at the boid's own unspun place, so a ripple stays where its drop\n"
    "    // fell), lifted along its home's normal (not its lagging position's: the\n"
    "    // waves would slide as the ball rises and falls). Crests glow brighter.\n"
    "    float oy = 1.0 - 2.0 * (float(i) + 0.5) / float(u_ball), ophi = float(i) * 2.3999632;\n"
    "    float orr = sqrt(max(1.0 - oy * oy, 0.0));\n"
    "    float sk = 0.0;\n"
    "    if (!text && pull * u_skin > 0.0) // (the skin read only where it shows)\n"
    "        sk = skin_at(vec3(cos(ophi) * orr, oy, sin(ophi) * orr)) * pull * u_skin;\n"
    "    imageStore(u_img, ivec2(i & 127, i >> 7),\n"
    "               vec4(p + (h.xyz - u_centre) * (0.2 / 3.0 * sk),\n"
    "                    h.w + min(length(v) / 12.0 + max(sk, 0.0) * 0.3, 0.99)));\n"
    "    uint c = cell_of(p);\n"
    "    cells.cr[i] = uvec2(c, u_count != 0 ? atomicAdd(counts.c[c], 1u) : 0u);\n"
    "}\n"
    ;

